-- Banco oficial Avanzado (90). Dificultad hard = Avanzado en la app (6 pts).
-- No hay columna de tiempo: la app ya usa 15 segundos para todas las trivias.
-- La columna Tema de cada fila se guarda en category.
-- Correcciones aplicadas respecto al original: A023 (Omar López, 2014-2015)
-- y A024 (Navegantes del Magallanes). Las demás van tal cual.
on conflict (code) where code is not null do nothing;

-- Cierra las sesiones hard abiertas que usan preguntas viejas antes de
-- desactivarlas. Mismo patrón del cierre perezoso de pulse_trivia_start:
-- completed_at = now() y available_at = now() para reintentar de inmediato
-- con el banco nuevo. No borra respuestas, puntos ni historial.
update public.pulse_trivia_sessions s
set completed_at = now(),
    available_at = now()
where s.completed_at is null
  and s.difficulty = 'hard'
  and exists (
    select 1
    from jsonb_array_elements_text(s.question_ids) item(id)
    join public.pulse_trivia_questions q on q.id = item.id
    where q.difficulty = 'hard'
      and q.status = 'active'
      and q.id not like 'trv_adv\_%' escape '\'
  );

update public.pulse_trivia_questions
set status = 'disabled'
where difficulty = 'hard'
  and status = 'active'
  and id not like 'trv_adv_%';
